async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8");
  let buffered = "";
  let line = 1;
  let delivered = 0;

  async function processLine(text, lineNumber) {
    if (text.endsWith("\r")) {
      text = text.slice(0, -1);
    }

    if (text.trim() === "") {
      return true;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    delivered++;
    return (await deliver(value, lineNumber)) !== false;
  }

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        buffered += decoder.decode();

        if (buffered.length > 0) {
          await processLine(buffered, line);
        }

        return delivered;
      }

      buffered += decoder.decode(chunk, { stream: true });

      let newline;
      while ((newline = buffered.indexOf("\n")) !== -1) {
        const text = buffered.slice(0, newline);
        buffered = buffered.slice(newline + 1);

        if (!(await processLine(text, line))) {
          return delivered;
        }

        line++;
      }
    }
  } finally {
    await input.close();
  }
}
